var n=`0921-hot-and-sour-soup`;var t=`world-0921`;var o=`CN`;var s=`east-asia`;var a=4;var r=36;var m={en:`Hot and Sour Soup`,ua:`Кисло-гострий суп`};var g={en:`Hot and Sour Soup is a China dish made with dried shiitake, bamboo shoots, tofu (firm), wood ear mushroom. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кисло-гострий суп, страва кухні країни Китай. Основні складники: сушені шиїтаке, пагони бамбука, твердий тофу, муер. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 12 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 12 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:12,i:[[`chicken-stock`,1e3,`ml`],[`dried-shiitake`,35,`g`],[`bamboo-shoots`,190,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`tofu-firm`,240,`g`],[`wood-ear-mushroom`,110,`g`],[`light-soy-sauce`,40,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`black-rice-vinegar`,75,`ml`],[`white-peppercorn`,3,`g`],[`cornstarch`,25,`g`],[`water`,65,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 3 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 3 хвилин до готовності й м’якості.`,t:[`poaching`],m:3,i:[[`chicken-egg`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,30,`g`]]}];var u={slug:n,id:t,country:`CN`,region:s,servings:4,minutes:36,title:m,text:g,steps:d};export{o as country,u as default,t as id,r as minutes,s as region,a as servings,n as slug,d as steps,g as text,m as title};